// Formatear mensaje Markdown para Telegram
const output = $json.output || $json;
const rawItem = $('Telegram Webhook Trigger').item.json;
const tgMessage = rawItem.body?.message || rawItem.message || {};
const autor = (tgMessage.from && tgMessage.from.first_name) ? tgMessage.from.first_name : (rawItem.body?.author || rawItem.author || 'Compañero');

const sentimientoEmoji = output.sentimiento === 'positivo' ? '🟢 Positivo' : (output.sentimiento === 'negativo' ? '🔴 Negativo' : '⚪ Neutro');

let msg = `🤖 *CommunityLab Assistant*\n\n`;

if (output.respuesta_chat) {
  msg += `${output.respuesta_chat}\n\n`;
}

if (output.tip_tecnico_faq) {
  msg += `💡 *Tip Técnico / FAQ:*\n${output.tip_tecnico_faq}\n\n`;
}

msg += `📊 *Análisis de Comunidad:*\n`;
msg += `• Sentimiento: ${sentimientoEmoji}\n`;
msg += `• Categoría: \`${output.tipo_contenido || 'general'}\`\n`;

if (output.temas_clave && output.temas_clave.length > 0) {
  msg += `• Temas: ${output.temas_clave.join(', ')}\n`;
}

if (output.post_linkedin) {
  msg += `\n🚀 *Post LinkedIn Propuesto:*\n${output.post_linkedin}\n`;
}

// Persistir en /home/node/data/paquete_procesado_canales_n8n.json
try {
  const fs = require('fs');
  const filePath = '/home/node/data/paquete_procesado_canales_n8n.json';
  let dataStore = {
    metadata_paquete: {
      generado_el: new Date().toISOString(),
      motor_orquestacion: "n8n_native_workflows",
      total_activos: 0,
      ultima_actualizacion: new Date().toISOString()
    },
    activos: []
  };

  if (fs.existsSync(filePath)) {
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      if (content.trim()) {
        dataStore = JSON.parse(content);
      }
    } catch (e) {}
  }

  const rawText = tgMessage.text || rawItem.body?.text || rawItem.body?.content || rawItem.texto || '';
  const autorUser = autor;
  const eventTs = (tgMessage.date || Date.now()).toString();

  const nuevoActivo = {
    interaccion: {
      id: `telegram_${eventTs}`,
      autor: autorUser,
      canal: "#telegram-comunidad",
      tipo: "consulta_dinamica",
      texto: rawText
    },
    activo: {
      sentimiento: output.sentimiento || "neutro",
      tipo_contenido: output.tipo_contenido || "feedback_general",
      temas_clave: Array.isArray(output.temas_clave) ? output.temas_clave : (output.temas_clave ? [output.temas_clave] : []),
      post_linkedin: output.post_linkedin || null,
      tip_tecnico_faq: output.tip_tecnico_faq || null
    },
    canal_origen_bot: "#telegram-comunidad",
    motor_orquestacion: "n8n_dynamic_channels",
    metadata_externa: {
      chat_id: tgMessage.chat?.id || rawItem.body?.chat_id,
      user_id: autorUser,
      ts: eventTs
    }
  };

  if (!dataStore.activos) dataStore.activos = [];
  dataStore.activos.unshift(nuevoActivo);
  dataStore.metadata_paquete = dataStore.metadata_paquete || {};
  dataStore.metadata_paquete.total_activos = dataStore.activos.length;
  dataStore.metadata_paquete.ultima_actualizacion = new Date().toISOString();

  fs.writeFileSync(filePath, JSON.stringify(dataStore, null, 2), 'utf8');
} catch (err) {}

const chatId = tgMessage.chat?.id || rawItem.body?.chat_id;
return [{
  json: {
    chat_id: chatId,
    mensaje_telegram: msg,
    respuesta_chat: output.respuesta_chat,
    tip_tecnico_faq: output.tip_tecnico_faq,
    post_linkedin: output.post_linkedin,
    sentimiento: output.sentimiento,
    tipo_contenido: output.tipo_contenido,
    temas_clave: output.temas_clave,
    raw_output: output
  }
}];

// Construir Discord Embed compatible con Webhooks de Discord
const output = $json.output || $json;

let color = 3447003; // Azul por defecto
if (output.sentimiento === 'positivo') color = 3066993; // Verde
if (output.sentimiento === 'negativo') color = 15158332; // Rojo
if (output.sentimiento === 'neutro') color = 15844367; // Amarillo

const fields = [
  { name: "📊 Sentimiento", value: (output.sentimiento || 'neutro').toUpperCase(), inline: true },
  { name: "🏷️ Categoría", value: output.tipo_contenido || 'General', inline: true },
  { name: "💡 Temas Clave", value: (output.temas_clave && output.temas_clave.length > 0) ? output.temas_clave.join(', ') : 'General', inline: false }
];

if (output.tip_tecnico_faq) {
  fields.push({ name: "🛠️ Tip Técnico / FAQ", value: output.tip_tecnico_faq.substring(0, 1024), inline: false });
}

if (output.post_linkedin) {
  fields.push({ name: "🚀 Post LinkedIn Generado", value: output.post_linkedin.substring(0, 1024), inline: false });
}

const discordPayload = {
  username: "CommunityLab Bot",
  avatar_url: "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/potion.png",
  content: output.respuesta_chat || "¡Consulta procesada exitosamente!",
  embeds: [{
    title: "CommunityLab AI Insight",
    color: color,
    fields: fields,
    footer: { text: "CommunityLab Hackathon Oracle & Alura • n8n Native Flow" },
    timestamp: new Date().toISOString()
  }]
};

// Persistir en /home/node/data/paquete_procesado_canales_n8n.json
try {
  const fs = require('fs');
  const filePath = '/home/node/data/paquete_procesado_canales_n8n.json';
  let dataStore = {
    metadata_paquete: {
      generado_el: new Date().toISOString(),
      motor_orquestacion: "n8n_native_workflows",
      total_activos: 0,
      ultima_actualizacion: new Date().toISOString()
    },
    activos: []
  };

  if (fs.existsSync(filePath)) {
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      if (content.trim()) {
        dataStore = JSON.parse(content);
      }
    } catch (e) {}
  }

  const rawItem = $('Discord Webhook Trigger').item.json;
  const rawText = rawItem.content || rawItem.body?.content || rawItem.text || rawItem.body?.text || '';
  const autorUser = rawItem.author || rawItem.body?.author || 'Usuario Discord';
  const eventTs = Date.now().toString();

  const nuevoActivo = {
    interaccion: {
      id: `discord_${eventTs}`,
      autor: autorUser,
      canal: "#discord-comunidad",
      tipo: "consulta_dinamica",
      texto: rawText
    },
    activo: {
      sentimiento: output.sentimiento || "neutro",
      tipo_contenido: output.tipo_contenido || "feedback_general",
      temas_clave: Array.isArray(output.temas_clave) ? output.temas_clave : (output.temas_clave ? [output.temas_clave] : []),
      post_linkedin: output.post_linkedin || null,
      tip_tecnico_faq: output.tip_tecnico_faq || null
    },
    canal_origen_bot: "#discord-comunidad",
    motor_orquestacion: "n8n_dynamic_channels",
    metadata_externa: {
      user_id: autorUser,
      ts: eventTs
    }
  };

  if (!dataStore.activos) dataStore.activos = [];
  dataStore.activos.unshift(nuevoActivo);
  dataStore.metadata_paquete = dataStore.metadata_paquete || {};
  dataStore.metadata_paquete.total_activos = dataStore.activos.length;
  dataStore.metadata_paquete.ultima_actualizacion = new Date().toISOString();

  fs.writeFileSync(filePath, JSON.stringify(dataStore, null, 2), 'utf8');
} catch (err) {}

return [{ json: discordPayload }];

// Construir Slack Blocks para respuesta estructurada en canal/hilo
const output = $json.output || $json;
const rawItem = $('Slack Events Webhook').item.json;
const slackEvent = rawItem.body?.event || {};

// Canal de destino: evento de Slack o fallback al canal oficial #all-g10-latam-06
const targetChannel = slackEvent.channel || rawItem.body?.channel || rawItem.channel || 'C0C3C2BPBSB';
const targetThreadTs = slackEvent.ts || rawItem.body?.thread_ts || rawItem.thread_ts || undefined;

const sent = (output.sentimiento || 'neutro').toLowerCase();
const sentimientoBadge = sent === 'positivo' ? ':large_green_circle: Positivo' : (sent === 'negativo' ? ':red_circle: Negativo' : ':large_yellow_circle: Neutro');

const blocks = [
  {
    "type": "header",
    "text": {
      "type": "plain_text",
      "text": "🤖 CommunityLab Assistant",
      "emoji": true
    }
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": output.respuesta_chat || "¡Mensaje procesado correctamente!"
    }
  },
  {
    "type": "context",
    "elements": [
      {
        "type": "mrkdwn",
        "text": `*Sentimiento:* ${sentimientoBadge} | *Categoría:* \`${output.tipo_contenido || 'General'}\` | *Temas:* ${(output.temas_clave && Array.isArray(output.temas_clave)) ? output.temas_clave.join(', ') : (output.temas_clave || 'N/A')}`
      }
    ]
  }
];

if (output.tip_tecnico_faq) {
  blocks.push({
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*💡 Tip Técnico / Solución:*\n${output.tip_tecnico_faq}`
    }
  });
}

if (output.post_linkedin) {
  blocks.push({
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*🚀 Post de LinkedIn Sugerido:*\n>${output.post_linkedin}`
    }
  });
}

// Persistencia en paquete_procesado_canales_n8n.json
try {
  const fs = require('fs');
  const filePath = '/home/node/data/paquete_procesado_canales_n8n.json';
  let dataStore = {
    metadata_paquete: {
      generado_el: new Date().toISOString(),
      motor_orquestacion: "n8n_native_workflows",
      total_activos: 0,
      ultima_actualizacion: new Date().toISOString()
    },
    activos: []
  };

  if (fs.existsSync(filePath)) {
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      if (content.trim()) {
        dataStore = JSON.parse(content);
      }
    } catch (e) {}
  }

  const rawText = slackEvent.text || rawItem.content || rawItem.body?.content || rawItem.text || rawItem.body?.text || '';
  const cleanText = rawText.replace(/<@[A-Z0-9]+>/g, '').trim();
  const autorUser = slackEvent.user || rawItem.author || rawItem.body?.author || 'Usuario Slack';
  const eventTs = slackEvent.ts || Date.now().toString();

  const nuevoActivo = {
    interaccion: {
      id: `slack_${eventTs.replace('.', '_')}`,
      autor: autorUser,
      canal: "#all-g10-latam-06",
      tipo: "consulta_dinamica",
      texto: cleanText || rawText
    },
    activo: {
      sentimiento: output.sentimiento || "neutro",
      tipo_contenido: output.tipo_contenido || "feedback_general",
      temas_clave: Array.isArray(output.temas_clave) ? output.temas_clave : (output.temas_clave ? [output.temas_clave] : []),
      post_linkedin: output.post_linkedin || null,
      tip_tecnico_faq: output.tip_tecnico_faq || null
    },
    canal_origen_bot: "#slack-comunidad",
    motor_orquestacion: "n8n_dynamic_channels",
    metadata_externa: {
      channel_id: targetChannel,
      user_id: autorUser,
      ts: eventTs
    }
  };

  if (!dataStore.activos) dataStore.activos = [];
  dataStore.activos.unshift(nuevoActivo);
  dataStore.metadata_paquete = dataStore.metadata_paquete || {};
  dataStore.metadata_paquete.total_activos = dataStore.activos.length;
  dataStore.metadata_paquete.ultima_actualizacion = new Date().toISOString();

  fs.writeFileSync(filePath, JSON.stringify(dataStore, null, 2), 'utf8');
} catch (err) {}

const payload = {
  channel: targetChannel,
  blocks: blocks,
  text: output.respuesta_chat || "CommunityLab Insight"
};
if (targetThreadTs) {
  payload.thread_ts = targetThreadTs;
}

return [{ json: payload }];

// Filtrar reintentos automaticos de Slack (evitar respuestas duplicadas)
const headers = $json.headers || {};
if (headers['x-slack-retry-num']) {
  // Descartar reintento para evitar duplicidad
  return [];
}
return [{ json: $json }];
